{"path": "/tmp/sv-11a05924d8264d7587adb7f803ca4528/Components/Pages/Settings/NotificationsSection.razor", "file_text": "@namespace sv_11a05924d8264d7587adb7f803ca4528.Components.Pages.Settings
@using sv_11a05924d8264d7587adb7f803ca4528.Services

<div class="settings-section">
    <h2>Notification Preferences</h2>

    @if (_prefs is null)
    {
        <p>Loading...</p>
    }
    else
    {
        <div class="notifications-form">
            <div class="toggle-group">
                <label class="toggle-item">
                    <input type="checkbox" @bind="_emailNotifications" />
                    <span>Email Notifications</span>
                </label>

                <label class="toggle-item">
                    <input type="checkbox" @bind="_pushNotifications" />
                    <span>Push Notifications</span>
                </label>

                <label class="toggle-item">
                    <input type="checkbox" @bind="_weeklyDigest" />
                    <span>Weekly Digest</span>
                </label>
            </div>

            <h3>Muted Channels</h3>
            <div class="channel-list">
                @foreach (var channel in _allChannels)
                {
                    <label class="channel-item">
                        <input type="checkbox"
                               checked="@_mutedChannels.Contains(channel)"
                               @onchange="e => ToggleChannel(channel, (bool)e.Value!)" />
                        <span>@channel</span>
                    </label>
                }
            </div>

            <div class="form-actions">
                <button class="btn-primary" @onclick="SaveAsync" disabled="@_saving">
                    @(_saving ? "Saving..." : "Save Preferences")
                </button>
            </div>

            @if (_showSuccess)
            {
                <div class="toast success">Preferences saved successfully!</div>
            }
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public ISettingsService SettingsService { get; set; } = default!;

    private NotificationPrefs? _prefs;
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = new();
    private bool _saving;
    private bool _showSuccess;

    // Sample channels — in a real app these would come from a service
    private static readonly string[] _allChannels = ["general", "announcements", "random", "engineering", "design", "marketing"];

    protected override async Task OnInitializedAsync()
    {
        _prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = _prefs.EmailNotifications;
        _pushNotifications = _prefs.PushNotifications;
        _weeklyDigest = _prefs.WeeklyDigest;
        _mutedChannels = new HashSet<string>(_prefs.MutedChannels);
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _showSuccess = false;

        var updated = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(updated);
        _prefs = updated;

        _saving = false;
        _showSuccess = true;

        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}
"}

{"path": "/tmp/sv-11a05924d8264d7587adb7f803ca4528/Components/Pages/Settings/ChangePasswordPanel.razor", "file_text": "@namespace sv_11a05924d8264d7587adb7f803ca4528.Components.Pages.Settings
@using sv_11a05924d8264d7587adb7f803ca4528.Services

<div class="password-panel">
    <button class="panel-toggle" @onclick="() => _expanded = !_expanded">
        <span>@(_expanded ? "▼" : "▶") Change Password</span>
    </button>

    @if (_expanded)
    {
        <div class="panel-content">
            <div class="form-group">
                <label for="currentPassword">Current Password</label>
                <input id="currentPassword" type="password" @bind="_currentPassword" />
            </div>

            <div class="form-group">
                <label for="newPassword">New Password</label>
                <input id="newPassword" type="password" @bind="_newPassword" />
            </div>

            <div class="form-group">
                <label for="confirmPassword">Confirm New Password</label>
                <input id="confirmPassword" type="password" @bind="_confirmPassword" />
            </div>

            @if (!string.IsNullOrEmpty(_error))
            {
                <div class="toast error">@_error</div>
            }

            @if (_showSuccess)
            {
                <div class="toast success">Password updated successfully!</div>
            }

            <button class="btn-primary" @onclick="UpdatePasswordAsync" disabled="@_saving">
                @(_saving ? "Updating..." : "Update Password")
            </button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public ISettingsService SettingsService { get; set; } = default!;

    private bool _expanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string _error = "";
    private bool _saving;
    private bool _showSuccess;

    private async Task UpdatePasswordAsync()
    {
        _error = "";
        _showSuccess = false;

        if (string.IsNullOrWhiteSpace(_currentPassword) ||
            string.IsNullOrWhiteSpace(_newPassword))
        {
            _error = "All password fields are required.";
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _error = "New password and confirmation do not match.";
            return;
        }

        _saving = true;

        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _showSuccess = true;
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _saving = false;
        }
    }
}
"}

{"path": "/tmp/sv-11a05924d8264d7587adb7f803ca4528/Components/Pages/Settings/ActiveSessionsTable.razor", "file_text": "@namespace sv_11a05924d8264d7587adb7f803ca4528.Components.Pages.Settings
@using sv_11a05924d8264d7587adb7f803ca4528.Services

<div class="sessions-section">
    <h3>Active Sessions</h3>

    @if (Sessions is null || Sessions.Count == 0)
    {
        <p>No active sessions.</p>
    }
    else
    {
        <table class="sessions-table">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th>Action</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in Sessions)
                {
                    <tr>
                        <td>@session.Device</td>
                        <td>@session.Location</td>
                        <td>@session.LastActive.ToString("g")</td>
                        <td>
                            @if (session.Id != CurrentSessionId)
                            {
                                <button class="btn-danger btn-small" @onclick="() => RequestRevoke(session)">
                                    Revoke
                                </button>
                            }
                            else
                            {
                                <span class="current-badge">Current</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    }

    @if (_sessionToRevoke is not null)
    {
        <div class="modal-overlay" @onclick="CancelRevoke">
            <div class="modal-dialog" @onclick:stopPropagation="true">
                <h4>Revoke Session</h4>
                <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> in <strong>@_sessionToRevoke.Location</strong>?</p>
                <div class="modal-actions">
                    <button class="btn-danger" @onclick="ConfirmRevokeAsync" disabled="@_revoking">
                        @(_revoking ? "Revoking..." : "Revoke")
                    </button>
                    <button class="btn-secondary" @onclick="CancelRevoke" disabled="@_revoking">Cancel</button>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public List<ActiveSession> Sessions { get; set; } = new();
    [Parameter] public string? CurrentSessionId { get; set; }
    [Parameter] public EventCallback<string> OnSessionRevoked { get; set; }

    private ActiveSession? _sessionToRevoke;
    private bool _revoking;

    private void RequestRevoke(ActiveSession session) => _sessionToRevoke = session;
    private void CancelRevoke() => _sessionToRevoke = null;

    private async Task ConfirmRevokeAsync()
    {
        if (_sessionToRevoke is null) return;

        _revoking = true;
        await OnSessionRevoked.InvokeAsync(_sessionToRevoke.Id);
        _revoking = false;
        _sessionToRevoke = null;
    }
}
"}

{"path": "/tmp/sv-11a05924d8264d7587adb7f803ca4528/Components/Pages/Settings/SecuritySection.razor", "file_text": "@namespace sv_11a05924d8264d7587adb7f803ca4528.Components.Pages.Settings
@using sv_11a05924d8264d7587adb7f803ca4528.Services

<div class="settings-section">
    <h2>Security Settings</h2>

    @if (_settings is null)
    {
        <p>Loading...</p>
    }
    else
    {
        <ChangePasswordPanel SettingsService="SettingsService" />

        <div class="tfa-section">
            <h3>Two-Factor Authentication</h3>
            <div class="tfa-status">
                <span class="status-indicator @(_settings.TwoFactorEnabled ? "enabled" : "disabled")">
                    @(_settings.TwoFactorEnabled ? "✓ Enabled" : "✗ Disabled")
                </span>
            </div>
            @if (_settings.LastPasswordChange.HasValue)
            {
                <p class="last-change">Last password change: @_settings.LastPasswordChange.Value.ToString("f")</p>
            }
        </div>

        <ActiveSessionsTable
            Sessions="_settings.Sessions"
            CurrentSessionId="@_settings.Sessions.FirstOrDefault()?.Id"
            OnSessionRevoked="RevokeSessionAsync" />
    }
</div>

@code {
    [Parameter, EditorRequired] public ISettingsService SettingsService { get; set; } = default!;

    private SecuritySettings? _settings;

    protected override async Task OnInitializedAsync()
    {
        _settings = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task RevokeSessionAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        // Reload to reflect the change
        _settings = await SettingsService.GetSecuritySettingsAsync();
    }
}
"}

{"path": "/tmp/sv-11a05924d8264d7587adb7f803ca4528/Components/Pages/Settings/AppearanceSection.razor", "file_text": "@namespace sv_11a05924d8264d7587adb7f803ca4528.Components.Pages.Settings
