@namespace sv_11a05924d8264d7587adb7f803ca4528.Components.Pages.Settings
@using sv_11a05924d8264d7587adb7f803ca4528.Services

<div class="settings-section">
    <h2>Security Settings</h2>

    @if (_settings is null)
    {
        <p>Loading...</p>
    }
    else
    {
        <ChangePasswordPanel SettingsService="SettingsService" />

        <div class="tfa-section">
            <h3>Two-Factor Authentication</h3>
            <div class="tfa-status">
                <span class="status-indicator @(_settings.TwoFactorEnabled ? "enabled" : "disabled")">
                    @(_settings.TwoFactorEnabled ? "✓ Enabled" : "✗ Disabled")
                </span>
            </div>
            @if (_settings.LastPasswordChange.HasValue)
            {
                <p class="last-change">Last password change: @_settings.LastPasswordChange.Value.ToString("f")</p>
            }
        </div>

        <ActiveSessionsTable
            Sessions="_settings.Sessions"
            CurrentSessionId="@_settings.Sessions.FirstOrDefault()?.Id"
            OnSessionRevoked="RevokeSessionAsync" />
    }
</div>

@code {
    [Parameter, EditorRequired] public ISettingsService SettingsService { get; set; } = default!;

    private SecuritySettings? _settings;

    protected override async Task OnInitializedAsync()
    {
        _settings = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task RevokeSessionAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        // Reload to reflect the change
        _settings = await SettingsService.GetSecuritySettingsAsync();
    }
}

@namespace sv_11a05924d8264d7587adb7f803ca4528.Components.Pages.Settings
@using sv_11a05924d8264d7587adb7f803ca4528.Services

<div class="settings-section">
    <h2>Appearance Settings</h2>

    @if (_settings is null)
    {
        <p>Loading...</p>
    }
    else
    {
        <div class="appearance-form">
            <div class="form-group">
                <label>Theme</label>
                <div class="radio-group">
                    @foreach (var theme in _themes)
                    {
                        <label class="radio-item">
                            <input type="radio" name="theme" value="@theme"
                                   checked="@(_theme == theme)"
                                   @onchange="() => _theme = theme" />
                            <span>@theme</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label>Font Size</label>
                <div class="radio-group">
                    @foreach (var size in _fontSizes)
                    {
                        <label class="radio-item">
                            <input type="radio" name="fontSize" value="@size"
                                   checked="@(_fontSize == size)"
                                   @onchange="() => _fontSize = size" />
                            <span>@size</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" @bind="_language">
                    @foreach (var lang in _languages)
                    {
                        <option value="@lang.Key">@lang.Value</option>
                    }
                </select>
            </div>

            <div class="form-group">
                <label class="toggle-item">
                    <input type="checkbox" @bind="_compactMode" />
                    <span>Compact Mode</span>
                </label>
            </div>

            <div class="live-preview @GetPreviewClasses()">
                <h4>Live Preview</h4>
                <p>This is how your content will look with the selected settings.</p>
                <div class="preview-card">
                    <strong>Sample Card</strong>
                    <p>Theme: @_theme | Font: @_fontSize | Compact: @(_compactMode ? "Yes" : "No")</p>
                </div>
            </div>

            <div class="form-actions">
                <button class="btn-primary" @onclick="SaveAsync" disabled="@_saving">
                    @(_saving ? "Saving..." : "Save")
                </button>
            </div>

            @if (_showSuccess)
            {
                <div class="toast success">Appearance settings saved!</div>
            }
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public ISettingsService SettingsService { get; set; } = default!;

    private AppearanceSettings? _settings;
    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;
    private bool _saving;
    private bool _showSuccess;

    private static readonly string[] _themes = ["Light", "Dark", "System"];
    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private static readonly Dictionary<string, string> _languages = new()
    {
        ["en"] = "English",
        ["es"] = "Español",
        ["fr"] = "Français",
        ["de"] = "Deutsch",
        ["ja"] = "日本語"
    };

    protected override async Task OnInitializedAsync()
    {
        _settings = await SettingsService.GetAppearanceAsync();
        _theme = _settings.Theme;
        _fontSize = _settings.FontSize;
        _language = _settings.Language;
        _compactMode = _settings.CompactMode;
    }

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{_theme.ToLowerInvariant()} preview-font-{_fontSize.ToLowerInvariant()}";
        if (_compactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _showSuccess = false;

        var updated = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(updated);
        _settings = updated;

        _saving = false;
        _showSuccess = true;

        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

