+                                   @onchange="() => _fontSize = size" />
+                            <span>@size</span>
+                        </label>
+                    }
+                </div>
+            </div>
+
+            <div class="form-group">
+                <label for="language">Language</label>
+                <select id="language" @bind="_language">
+                    @foreach (var lang in _languages)
+                    {
+                        <option value="@lang.Key">@lang.Value</option>
+                    }
+                </select>
+            </div>
+
+            <div class="form-group">
+                <label class="toggle-item">
+                    <input type="checkbox" @bind="_compactMode" />
+                    <span>Compact Mode</span>
+                </label>
+            </div>
+
+            <div class="live-preview @GetPreviewClasses()">
+                <h4>Live Preview</h4>
+                <p>This is how your content will look with the selected settings.</p>
+                <div class="preview-card">
+                    <strong>Sample Card</strong>
+                    <p>Theme: @_theme | Font: @_fontSize | Compact: @(_compactMode ? "Yes" : "No")</p>
+                </div>
+            </div>
+
+            <div class="form-actions">
+                <button class="btn-primary" @onclick="SaveAsync" disabled="@_saving">
+                    @(_saving ? "Saving..." : "Save")
+                </button>
+            </div>
+
+            @if (_showSuccess)
+            {
+                <div class="toast success">Appearance settings saved!</div>
+            }
+        </div>
+    }
+</div>
+
+@code {
+    [Parameter, EditorRequired] public ISettingsService SettingsService { get; set; } = default!;
+
+    private AppearanceSettings? _settings;
+    private string _theme = "System";
+    private string _fontSize = "Medium";
+    private string _language = "en";
+    private bool _compactMode;
+    private bool _saving;
+    private bool _showSuccess;
+
+    private static readonly string[] _themes = ["Light", "Dark", "System"];
+    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
+    private static readonly Dictionary<string, string> _languages = new()
+    {
+        ["en"] = "English",
+        ["es"] = "Español",
+        ["fr"] = "Français",
+        ["de"] = "Deutsch",
+        ["ja"] = "日本語"
+    };
+
+    protected override async Task OnInitializedAsync()
+    {
+        _settings = await SettingsService.GetAppearanceAsync();
+        _theme = _settings.Theme;
+        _fontSize = _settings.FontSize;
+        _language = _settings.Language;
+        _compactMode = _settings.CompactMode;
+    }
+
+    private string GetPreviewClasses()
+    {
+        var classes = $"preview-theme-{_theme.ToLowerInvariant()} preview-font-{_fontSize.ToLowerInvariant()}";
+        if (_compactMode) classes += " preview-compact";
+        return classes;
+    }
+
+    private async Task SaveAsync()
+    {
+        _saving = true;
+        _showSuccess = false;
+
+        var updated = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
+        await SettingsService.SaveAppearanceAsync(updated);
+        _settings = updated;
+
+        _saving = false;
+        _showSuccess = true;
+
+        _ = HideToastAfterDelay();
+    }
+
+    private async Task HideToastAfterDelay()
+    {
+        await Task.Delay(3000);
+        _showSuccess = false;
+        await InvokeAsync(StateHasChanged);
+    }
+}
+

